schemas.schema-01-systematic.prisma:
/// Root tenant entity representing companies/organizations in the erpHrm
/// system.
///
/// This table serves as the aggregate root for all organization-scoped data
/// isolation. Each organization contains identity information (name,
/// description, logo) and configuration settings (currency, timezone, fiscal
/// calendar) that define how the organization operates within the system.
///
/// Organizations are owned by a User (referenced via owner_id) who has
/// administrative control. All other domain entities (members, roles,
/// departments, projects, tasks, etc.) belong to an organization and are
/// isolated from other organizations.
///
/// Soft deletion is supported via deleted_at to allow for data recovery and
/// maintain referential integrity with historical records.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model erp_hrm_organizations {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owner user's {@link erp_hrm_members.id}. The user who created and owns
  /// this organization.
  owner_id String @db.Uuid

  /// Organization name. Display name for the company/organization.
  name String

  /// Optional organization description. Brief summary of the organization's
  /// purpose or business.
  description String?

  /// Optional URL to the organization's logo image.
  logo_url String? @db.VarChar(80000)

  /// Default currency for the organization in ISO 4217 format (e.g., USD, EUR,
  /// KRW). Used for financial calculations and reporting.
  currency String

  /// Organization's default timezone in IANA format (e.g., America/New_York,
  /// Asia/Seoul). Used for datetime localization.
  timezone String

  /// Month when the fiscal year starts (1-12). Used for financial reporting
  /// and analytics.
  fiscal_year_start_month Int @db.Integer

  /// Timestamp when the organization was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the organization was last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp. Null if active, set when organization is deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  owner erp_hrm_members @relation(fields: [owner_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  organizationMembers erp_hrm_organization_members[]
  roles erp_hrm_roles[]
  departments erp_hrm_departments[]
  contracts erp_hrm_contracts[]
  projects erp_hrm_projects[]
  activityLogs erp_hrm_activity_logs[]

  //----
  // INDEXES
  //----
  @@unique([name])
  @@index([owner_id])
  @@index([created_at])
}

schemas.schema-03-organization.prisma:
/// Employee records linking global users to specific organizations. Each
/// record represents a membership that connects a user account to an
/// organizational context, enabling the user to perform work within that
/// organization. Contains role assignment for access control, optional
/// department placement for organizational structure, position/title for
/// hierarchy identification, employment type classification, and activation
/// status for lifecycle management. Serves as the bridge entity that makes
/// all work data (timelogs, timesheets, project assignments)
/// organization-scoped.
///
/// Key business relationships:
/// - Belongs to {@link erp_hrm_organizations} via organization_id
/// - Links to global {@link erp_hrm_members} via user_id
/// - Assigned {@link erp_hrm_roles} for permissions
/// - Optionally belongs to {@link erp_hrm_departments}
/// - Has many {@link erp_hrm_contracts}, {@link erp_hrm_project_members},
/// {@link erp_hrm_timelogs}, {@link erp_hrm_timesheets}, {@link
/// erp_hrm_timers}
///
/// @namespace Organization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model erp_hrm_organization_members {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged organization's {@link erp_hrm_organizations.id}.
  organization_id String @db.Uuid

  /// Linked global user's {@link erp_hrm_members.id}.
  user_id String @db.Uuid

  /// Assigned role's {@link erp_hrm_roles.id} determining permissions.
  role_id String @db.Uuid

  /// Optional department assignment's {@link erp_hrm_departments.id}.
  department_id String? @db.Uuid

  /// Optional job title or position within the organization (e.g., 'Senior
  /// Developer', 'Project Manager').
  position String?

  /// Classification of working relationship: 'full_time', 'part_time',
  /// 'contractor', or 'intern'.
  employment_type String

  /// Activation status indicating whether the member can perform work
  /// activities. true=active, false=deactivated.
  is_active Boolean

  /// Timestamp when the membership was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last membership update.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for preserving historical work records.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  organization erp_hrm_organizations @relation(fields: [organization_id], references: [id], onDelete: Cascade)
  user erp_hrm_members @relation(fields: [user_id], references: [id], onDelete: Cascade)
  role erp_hrm_roles @relation(fields: [role_id], references: [id], onDelete: Cascade)
  department erp_hrm_departments? @relation(fields: [department_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  contracts erp_hrm_contracts[]
  projectMembers erp_hrm_project_members[]
  assignedTasks erp_hrm_tasks[]
  timelogs erp_hrm_timelogs[]
  timesheets erp_hrm_timesheets[] @relation("erp_hrm_timesheets_of_organization_member_id")
  reviewedTimesheets erp_hrm_timesheets[] @relation("erp_hrm_timesheets_of_reviewed_by_id")
  timers erp_hrm_timers[]

  //----
  // INDEXES
  //----
  @@index([user_id])
  @@index([role_id])
  @@index([department_id])
  @@unique([organization_id, user_id])
  @@index([organization_id, is_active])
}

