  /// Timestamp when the timesheet was submitted for approval. Null while in
  /// draft status.
  submitted_at DateTime? @db.Timestamptz

  /// Timestamp when the timesheet was reviewed (approved or rejected). Null
  /// until review occurs.
  reviewed_at DateTime? @db.Timestamptz

  /// Explanation provided when a timesheet is rejected. Null for approved
  /// timesheets or when not yet reviewed.
  rejection_reason String?

  /// Timestamp when the timesheet record was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp of the last update to this timesheet record.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp. Null if the timesheet is active, set when soft
  /// deleted for data retention.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  organizationMember erp_hrm_organization_members  @relation("erp_hrm_timesheets_of_organization_member_id", fields: [organization_member_id], references: [id], onDelete: Cascade)
