        email: typia.random<string & tags.Format<"email">>(),
        password: "AnyPass123!",
      } satisfies IErpHrmMember.ILogin,
    });
  } catch (error) {
    if (typia.is<api.HttpError>(error)) {
      nonExistentError = error;
    } else {
