          organizationId: organization.id,
          userId: anotherEmployee.id,
          employmentType: "part_time",
          isActive: true,
        } as DeepPartial<IErpHrmOrganizationMember.ICreate>,
      },
    );
  typia.assert(anotherMember);
}

