      body: {
        employmentType: "part-time",
      } satisfies IErpHrmContract.IRequest,
    });
  typia.assert(resultByEmploymentType);
  TestValidator.equals(
    "data array empty for non-matching employment type",
    resultByEmploymentType.data.length,
    0,
  );
  TestValidator.equals(
