    {
      body: {
        status: "completed",
      } satisfies Partial<IErpHrmProject.ICreate>,
    },
  );
  typia.assert(completedProject);
  // 4. Search without filters
  const searchResult = await api.functional.erpHrm.member.projects.index(
    memberConnection,
