  const employeeRole = await generate_random_erp_hrm_member_roles_create(
    adminConnection,
    {
      body: {
        name: "Standard Employee",
        description: "Basic employee role",
        permissions: [] satisfies IErpHrmRolePermission.ICreate[],
      },
    },
  );
