    body: IErpHrmProject.IUpdate,
  ): Promise<IErpHrmProject> {
    try {
      return await patchErpHrmMemberProjectsProjectIdArchive({
        member,
        projectId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

