@Controller("/erpHrm/member/projects/:projectId/members")
export class ErphrmMemberProjectsMembersController {
  /**
   * Create a new project member assignment.
   *
   * This operation adds an organization member to a project with a specific role designation. Only users with project management permission can assign members to projects. The role can be either 'member' (standard participation rights) or 'project-lead' (task management authority within the project).
   *
   * Each organization member can only be assigned once to a project due to the unique constraint on project_id and organization_member_id. Attempting to assign an already-assigned member will result in a validation error.
   *
   * Project membership determines access to project data and operations:
   * - Members can view project information, tasks, and log time
   * - Project leads can additionally create and manage tasks within the project
   * - Non-members cannot access project data or operations
   *
   * The assignment links an organization member (through their organization_member_id) to the project, establishing their eligibility for task assignments and time tracking within that project context.
   *
   * @param connection
   * @param projectId Unique identifier of the project (global scope)
   * @param body Creation parameters for project member assignment
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Insert a new record into erp_hrm_project_members table.
   *
   * Implementation steps:
   * 1. Validate the projectId exists and belongs to the current organization context
   * 2. Validate the organization_member_id exists and belongs to the same organization
   * 3. Check the requesting user has project management permission
   * 4. Validate role is either 'member' or 'project-lead' (valid values from DB enum)
   * 5. Check @@unique([project_id, organization_member_id]) constraint - reject if duplicate with proper error message
   * 6. Generate UUID for id field
   * 7. Set created_at and updated_at to current timestamp
   * 8. Insert record with: id, project_id=projectId, organization_member_id, role, created_at, updated_at
   * 9. Return the newly created project member record joined with organization member and user details
   *
   * Business rule enforcement:
   * - Only users with project management permission can execute this operation
   * - Cannot assign already-assigned members to the same project
   * - Role values must be validated against allowed enum: 'member' | 'project-lead'
   *
   * Edge case handling:
   * - If organization member is deactivated, may still assign but log warning
   * - Soft-deleted records (deleted_at != null) should be considered as not existing for duplicate check
   * - Cascade delete on project or organization member deletion is handled by DB constraint
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IErpHrmProjectMember.ICreate,
  ): Promise<IErpHrmProjectMember> {
    try {
      return await postErpHrmMemberProjectsProjectIdMembers({
        member,
        projectId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a filtered and paginated list of project members for a specific project.
   *
   * This operation provides search capabilities for viewing project team composition. Project members represent the assignment of organization members to projects with specific role designations.
   *
   * The response includes project member details with their role ('member' or 'project-lead'), along with nested organization member and project information. Results are paginated and support filtering by role and organization member attributes.
   *
   * Project access control is enforced: only users with appropriate permissions can view project members. Typically, project leads can view members of their assigned projects, while users with project management permission can view members across all projects.
   *
   * Each project member record includes the assigned organization member's details, allowing identification of team members by name, position, and department. The role field indicates the member's authority level within the project context.
   *
   * @param connection
   * @param projectId Target project's ID (UUID format)
   * @param body Search criteria and pagination parameters for filtering project members
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query erp_hrm_project_members table filtered by the provided projectId.
