    projectId: string,
    @TypedBody()
    body: IErpHrmProjectMember.IRequest,
  ): Promise<IPageIErpHrmProjectMember.ISummary> {
    try {
      return await patchErpHrmMemberProjectsProjectIdMembers({
        member,
        projectId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve detailed information about a specific project member assignment.
   *
   * This operation returns a single project member record identified by its unique ID, scoped within the context of a specific project. The response includes the project member's assigned role (either 'member' for standard participation or 'project-lead' for task management authority), timestamps for creation and updates, and the linked organization member details.
   *
   * The project member entity represents the many-to-many relationship between projects and organization members, allowing employees to participate in multiple projects with different roles per project. Project-level roles are independent of organization-level roles - an employee may have limited organization permissions while serving as a project-lead on specific projects.
   *
   * Access control requires the requesting user to be a member of the specified project. Non-members cannot retrieve member details for projects they are not assigned to. This ensures project data isolation and prevents unauthorized access to team member information across projects.
   *
   * Related operations:
   * - PATCH /projects/{projectId}/members: List all members of a project
   * - POST /projects/{projectId}/members: Assign a new member to the project (requires project management permission)
   * - PUT /projects/{projectId}/members/{projectMemberId}: Update member role (requires project management permission)
   * - DELETE /projects/{projectId}/members/{projectMemberId}: Remove member from project (requires project management permission)
   *
   * @param connection
   * @param projectId Parent project's ID (UUID) for access control context
   * @param projectMemberId Target project member record's ID (primary key)
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Implementation steps for retrieving a project member:
   *
   * 1. Validate both path parameters exist and are valid UUID format
   * 2. Verify the requesting user has project access (is a member of the specified project) - return 403 Forbidden if not
   * 3. Query erp_hrm_project_members table where id = projectMemberId AND project_id = projectId
   * 4. Include the organizationMember relation data in the response
   * 5. Join with erp_hrm_organization_members to get member details including user profile information
   * 6. Handle case where record not found: return 404 Not Found with appropriate error message
   * 7. Return the complete IErpHrmProjectMember object with nested organization member details
   *
   * Authorization: Member actor with project membership. The requesting member must be assigned to the project specified in projectId.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":projectMemberId")
  public async at(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("projectId")
    projectId: string & tags.Format<"uuid">,
    @TypedParam("projectMemberId")
    projectMemberId: string & tags.Format<"uuid">,
  ): Promise<IErpHrmProjectMember> {
    try {
      return await getErpHrmMemberProjectsProjectIdMembersProjectMemberId({
        member,
        projectId,
        projectMemberId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update an existing project member's role designation within a project.
   *
   * This operation allows authorized users to modify a project member's role from 'member' to 'project-lead' or vice versa. The role designation determines the member's permissions within the project context: regular members have standard participation rights, while project-leads have task management authority including creating, editing, and changing task statuses within their assigned projects.
   *
   * Project membership modification requires project management permission at the organization level. Project leads who do not hold this organization-level permission cannot modify memberships, even within projects where they serve as leads. This ensures centralized control over project team composition.
   *
   * The operation updates the role field and automatically updates the updated_at timestamp. The record is identified by its projectMemberId primary key within the specific project context.
   *
   * @param connection
