import { postErpHrmMemberProjectsProjectIdTasks } from "../../../../../providers/postErpHrmMemberProjectsProjectIdTasks";
import { putErpHrmMemberProjectsProjectIdTasksTaskId } from "../../../../../providers/putErpHrmMemberProjectsProjectIdTasksTaskId";

@Controller("/erpHrm/member/projects/:projectId/tasks")
export class ErphrmMemberProjectsTasksController {
  /**
   * Create a new task within the specified project.
   *
   * This operation allows authorized users to create tasks within a project context. Tasks represent discrete units of work that can be assigned to organization members and tracked through a status workflow. The created task automatically becomes part of the project's task collection.
   *
   * Task creation requires the user to be a project lead for this specific project or have organization-level project management permissions. Project members with only the member role cannot create tasks.
   *
   * The request body must include at minimum the task title. Optional fields include description, status (defaults to 'Open'), priority (defaults to 'Medium'), due date, estimated hours, assignment to an organization member, and parent task for creating sub-tasks. When a parent task is specified, the new task becomes a child task limited to single-level nesting.
   *
   * Upon successful creation, the system returns the complete task object including the generated UUID, timestamps, and all provided attributes. The task status change to 'Open' is automatically recorded in the task history.
   *
   * Related operations include GET /projects/{projectId}/tasks for listing project tasks and GET /tasks/{taskId} for retrieving a specific task's details.
   *
   * @param connection
   * @param projectId Target project's ID
   * @param body Task creation data including title, description, status, priority, due date, estimated hours, assignment, and optional parent task for sub-task creation
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Extract projectId from path parameter. Validate the user has permission to create tasks in this project - check if user is project lead for this project or has organization-level project management permission (see section 437).
   *
